class Solution {
  public String lexSmallestAfterDeletion(String s) {
    int n = s.length();
    int[] later = new int[26], inStack = new int[26];
    for (int i = 0; i < n; i++) later[s.charAt(i) - 'a']++;
    char[] stack = new char[n];
    int sp = 0;
    for (int i = 0; i < n; i++) {
      char c = s.charAt(i);
      later[c - 'a']--;
      while (sp > 0 && stack[sp - 1] > c) {
        int t = stack[sp - 1] - 'a';
        if (inStack[t] > 1 || later[t] > 0) {
          inStack[t]--;
          sp--;
        } else break;
      }
      stack[sp++] = c;
      inStack[c - 'a']++;
    }
    while (sp > 0 && inStack[stack[sp - 1] - 'a'] > 1) {
      inStack[stack[sp - 1] - 'a']--;
      sp--;
    }
    return new String(stack, 0, sp);
  }
}
